function validate([nums, numsDivide]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (numsDivide.length < 1 || numsDivide.length > 100000) return 'numsDivide needs 1 to 100000 values.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1e9;
  if (!nums.every(ok) || !numsDivide.every(ok)) return 'Every value is an integer from 1 to 10^9.';
  return null;
}

