function minOperations(nums, numsDivide) {
  const gcd = (a, b) => {
    while (b !== 0) {
      [a, b] = [b, a % b];
    }
    return a;
  };

  let common = 0;
  for (const value of numsDivide) {
    common = gcd(common, value);
  }

  let smallest = Infinity;
  for (const num of nums) {
    if (common % num === 0 && num < smallest) {
      smallest = num;
    }
  }
  if (smallest === Infinity) {
    return -1;
  }

  let deletions = 0;
  for (const num of nums) {
    if (num < smallest) {
      deletions++;
    }
  }
  return deletions;
}

