function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const gcd = (a, b) => { while (b) [a, b] = [b, a % b]; return a; };
  const small = size === 'small';
  const base = small ? int(1, 12) : [2, 3, 5, 7].reduce((acc, p) => acc * p ** int(0, 3), 1);
  const numsDivide = Array.from({ length: small ? int(1, 5) : 2000 }, () => base * int(1, small ? 4 : Math.floor(1e9 / base)));
  const common = numsDivide.reduce(gcd, 0);
  const divisors = [];
  for (let d = 1; d * d <= common; d++) if (common % d === 0) divisors.push(d, common / d);
  divisors.sort((a, b) => a - b);
  // Usually plant a few divisors (biased toward large ones); otherwise the answer is likely -1.
  const planted = [];
  if (rand() < 0.8) {
    for (let k = int(1, 3); k > 0; k--) planted.push(divisors[Math.floor(divisors.length * Math.sqrt(rand()))]);
  }
  const least = planted.length ? Math.min(...planted) : 1000;
  const top = small ? 15 : Math.min(1e9, Math.max(1000, least * int(1, 40)));
  // The rest are values that (almost always) do not divide common.
  const other = () => {
    let v = int(2, top);
    for (let tries = 0; tries < 20 && common % v === 0; tries++) v = int(2, top);
    return v;
  };
  const nums = Array.from({ length: small ? int(1, 8) : 2000 }, other);
  for (const d of planted) nums[int(0, nums.length - 1)] = d;
  return [nums, numsDivide];
}
